## 1. Identification Strategy
- Method: Sharp Regression Discontinuity Design (RDD).
- Why: Wilderness designation is determined by an elevation cutoff. Units just above the cutoff are treated (inside wilderness), and units just below are controls (outside). Comparing outcomes infinitesimally around the cutoff identifies the causal jump in deforestation due to designation.
- Estimand: The local average treatment effect at the elevation cutoff (the discontinuity in deforestation rates).
- Key assumptions:
  - Continuity: In the absence of treatment, expected deforestation would vary smoothly with elevation at the cutoff.
  - No precise manipulation: Agents cannot precisely sort around the cutoff elevation.
  - Sharp assignment: Treatment switches deterministically at the cutoff (we verify by matching treated to a threshold in the running variable).
- Implementation choices:
  - Local linear RD with triangular kernel within the near-cutoff window provided by the data (near_cutoff == 1), centering elevation at the detected threshold.
  - Robustness: bandwidth sensitivity (half-window), higher-order polynomial (quadratic), donut RD (exclude tight neighborhood), a global polynomial specification, and a local randomization diff-in-means. We also attempt a density (McCrary) test if the package is available.

## 2. R Code
```r
# Complete, self-contained R code that:
# - Reads the CSV file from the path provided
# - Runs the appropriate causal analysis
# - Prints a clear numerical result (coefficient, CAR, etc.)
# - Includes basic robustness checks

# Load data
df <- read.csv("experiments/exp_b/data/s93_data.csv", stringsAsFactors = FALSE)

# Basic checks
stopifnot(all(c("running_var","treated","y","near_cutoff") %in% names(df)))

# Helper: detect the cutoff that best matches a sharp threshold assignment
find_cutoff <- function(x, t){
  ux <- sort(unique(x))
  if(length(ux) < 2){
    stop("Insufficient variation in running variable to detect cutoff.")
  }
  # Candidate thresholds: midpoints between consecutive sorted unique values
  cand <- (ux[-1] + ux[-length(ux)]) / 2
  miscls <- sapply(cand, function(c) sum(abs((x >= c) - t)))
  best_idx <- which.min(miscls)
  best_c <- cand[best_idx]
  list(
    c = best_c,
    misclass = miscls[best_idx],
    rate = miscls[best_idx] / length(x)
  )
}

cinfo <- find_cutoff(df$running_var, df$treated)
c_hat <- as.numeric(cinfo$c)

# Center running variable at detected cutoff
df$x_c <- df$running_var - c_hat

# Load robust inference packages
if (!requireNamespace("sandwich", quietly = TRUE)) {
  install.packages("sandwich", repos = "https://cloud.r-project.org")
}
if (!requireNamespace("lmtest", quietly = TRUE)) {
  install.packages("lmtest", repos = "https://cloud.r-project.org")
}
library(sandwich)
library(lmtest)

# Local linear RD estimator (triangular kernel) helper
rd_local_linear <- function(dat, degree = 1, use_window = TRUE, half_window = FALSE, donut_frac = 0){
  sub <- dat
  if(use_window){
    sub <- subset(sub, near_cutoff == 1)
  }
  # Guard against empty subsets
  if(nrow(sub) < 10){
    return(list(est = NA, se = NA, p = NA, N = nrow(sub), bw = NA))
  }
  # Optionally shrink bandwidth by half using the empirical |x| median within window
  if(half_window){
    bw_half <- stats::quantile(abs(sub$x_c), probs = 0.5, na.rm = TRUE)
    sub <- sub[abs(sub$x_c) <= bw_half, , drop = FALSE]
  }
  if(nrow(sub) < 10){
    return(list(est = NA, se = NA, p = NA, N = nrow(sub), bw = NA))
  }
  # Donut RD: exclude a central neighborhood
  H_full <- max(abs(sub$x_c))
  if(is.na(H_full) || H_full == 0){
    return(list(est = NA, se = NA, p = NA, N = nrow(sub), bw = NA))
  }
  if(donut_frac > 0){
    sub <- sub[abs(sub$x_c) > donut_frac * H_full, , drop = FALSE]
  }
  if(nrow(sub) < 10){
    return(list(est = NA, se = NA, p = NA, N = nrow(sub), bw = NA))
  }
  # Bandwidth and triangular weights
  H <- max(abs(sub$x_c))
  if(H <= 0){
    return(list(est = NA, se = NA, p = NA, N = nrow(sub), bw = NA))
  }
  w <- pmax(0, 1 - abs(sub$x_c)/H)

  # Build formula
  if(degree == 1){
    fm <- y ~ treated + x_c + treated:x_c
  } else if(degree == 2){
    sub$x_c2 <- sub$x_c^2
    fm <- y ~ treated + x_c + x_c2 + treated:x_c + treated:x_c2
  } else {
    stop("degree must be 1 or 2 for this helper.")
  }

  fit <- lm(fm, data = sub, weights = w)
  ct <- tryCatch(
    coeftest(fit, vcov = vcovHC(fit, type = "HC1")),
    error = function(e) NULL
  )
  if(is.null(ct) || !"treated" %in% rownames(ct)){
    return(list(est = NA, se = NA, p = NA, N = nrow(sub), bw = H))
  }
  est <- as.numeric(ct["treated", "Estimate"])
  se  <- as.numeric(ct["treated", "Std. Error"])
  p   <- as.numeric(ct["treated", "Pr(>|t|)"])
  list(est = est, se = se, p = p, N = nrow(sub), bw = H)
}

# Main RD estimate: local linear within near-cutoff window
main_res <- rd_local_linear(df, degree = 1, use_window = TRUE, half_window = FALSE, donut_frac = 0)

# Robustness 1: Half-window (narrower bandwidth)
half_res <- rd_local_linear(df, degree = 1, use_window = TRUE, half_window = TRUE, donut_frac = 0)

# Robustness 2: Quadratic in running variable within window
quad_res <- rd_local_linear(df, degree = 2, use_window = TRUE, half_window = FALSE, donut_frac = 0)

# Robustness 3: Donut RD (drop the central 10% of the window)
donut_res <- rd_local_linear(df, degree = 1, use_window = TRUE, half_window = FALSE, donut_frac = 0.10)

# Robustness 4: Global parametric (quadratic) using the full sample
global_res <- rd_local_linear(df, degree = 2, use_window = FALSE, half_window = FALSE, donut_frac = 0)

# Local randomization check: diff-in-means within near-cutoff window
sub_win <- subset(df, near_cutoff == 1)
diff_fit <- lm(y ~ treated, data = sub_win)
diff_ct  <- coeftest(diff_fit, vcov = vcovHC(diff_fit, type = "HC1"))
diff_est <- as.numeric(diff_ct["treated","Estimate"])
diff_se  <- as.numeric(diff_ct["treated","Std. Error"])
diff_p   <- as.numeric(diff_ct["treated","Pr(>|t|)"])
diff_N   <- nrow(sub_win)

# Optional: McCrary density test (if available)
dens_p <- NA
if (requireNamespace("rddensity", quietly = TRUE)) {
  suppressWarnings({
    rd_dens <- tryCatch(rddensity::rddensity(x = df$x_c, c = 0), error = function(e) NULL)
    if(!is.null(rd_dens)){
      srd <- tryCatch(summary(rd_dens), error = function(e) NULL)
      if(!is.null(srd) && !is.null(srd$test$pv)){
        dens_p <- as.numeric(srd$test$pv)
      }
    }
  })
}

# Print results
cat(sprintf("Detected elevation cutoff (c): %.4f\n", c_hat))
cat(sprintf("Misclassification rate for sharp rule 1{running_var >= c}: %.2f%% (%d/%d)\n",
            100*cinfo$rate, cinfo$misclass, nrow(df)))
cat("\nMain RD estimate (local linear, triangular kernel, near-cutoff window):\n")
cat(sprintf("  tau = %.4f, SE = %.4f, p = %.4f, N = %d, window half-range = %.4f\n",
            main_res$est, main_res$se, main_res$p, main_res$N, main_res$bw))

cat("\nRobustness checks:\n")
cat(sprintf("  Half-window:             tau = %.4f, SE = %.4f, p = %.4f, N = %d\n",
            half_res$est, half_res$se, half_res$p, half_res$N))
cat(sprintf("  Quadratic (within win):  tau = %.4f, SE = %.4f, p = %.4f, N = %d\n",
            quad_res$est, quad_res$se, quad_res$p, quad_res$N))
cat(sprintf("  Donut (drop inner 10%%):  tau = %.4f, SE = %.4f, p = %.4f, N = %d\n",
            donut_res$est, donut_res$se, donut_res$p, donut_res$N))
cat(sprintf("  Global quadratic (full): tau = %.4f, SE = %.4f, p = %.4f, N = %d\n",
            global_res$est, global_res$se, global_res$p, global_res$N))

cat("\nLocal randomization (diff-in-means within near-cutoff window):\n")
cat(sprintf("  Diff = %.4f, SE = %.4f, p = %.4f, N = %d\n",
            diff_est, diff_se, diff_p, diff_N))

if(!is.na(dens_p)){
  cat(sprintf("\nMcCrary density test p-value (no sorting at cutoff): %.4f\n", dens_p))
} else {
  cat("\nMcCrary density test not run (package 'rddensity' unavailable or failed).\n")
}
```

## 3. Expected Findings
- Sign: Negative. Wilderness designation should reduce deforestation; thus, the RD jump (treated just inside minus control just outside) is expected to be below zero.
- Magnitude: On the order of 5–15 percentage points (−0.05 to −0.15) in deforestation rates at the cutoff, given the outcome scale in the preview (values around 0.1–0.5) and typical impacts of strict protection in comparable contexts.
- Robustness: Estimates should be stable across bandwidth choices and functional forms; a McCrary test should not reject no manipulation.
